const requestedApp=new URLSearchParams(window.location.search).get("app");let current=apps[requestedApp]?requestedApp:"hub";const $=s=>document.querySelector(s);function render(){const app=apps[current];document.documentElement.style.setProperty("--accent",app.accent);$("#product").textContent=app.name;$("#document").textContent=app.context;$("#navItems").innerHTML=app.nav.map((n,i)=>`<button class="${i===0?'active':''}">${n}</button>`).join("");$("#main").innerHTML=`<p class="eyebrow">Artifice ${app.name}</p><h1>${app.title}</h1><p class="lede">${app.lede}</p>${app.main}`;$("#inspector").innerHTML=app.inspect;$("#appMenu").hidden=true}document.addEventListener("click",e=>{const action=e.target.closest("[data-action]")?.dataset.action;if(action==="switcher")$("#appMenu").hidden=!$("#appMenu").hidden;if(action==="theme")document.documentElement.dataset.theme=document.documentElement.dataset.theme==="dark"?"light":"dark";if(action==="activity")$("#activity").classList.toggle("open");if(action==="nav")$("#nav").classList.toggle("open");const app=e.target.closest("[data-app]")?.dataset.app;if(app){current=app;render()}});render();
